{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Emtricitabine has an absolute oral bioavailability of 93% in humans, with systemic exposure unaffected by food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Theophylline has essentially 100% absolute oral bioavailability in healthy subjects, indicating no first-pass effect.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Cladribine tablet absolute oral bioavailability is approximately 40%, which remains above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All evidence molecules have high assay-transfer scores (≥0.988) and support oral bioavailability above the 20% threshold; most values are 60–100%, and the lower numeric values such as cladribine ~40% and didanosine fasting 22–38% still exceed 20%.",
  "evidence_gaps": [
    "Molecule 1 includes didanosine records under the same grouping as emtricitabine; these inconsistent cards were discounted as a provenance conflict.",
    "Molecule 7 provides only qualitative 'high bioavailability' without a numeric F value, so it supports high but is less quantitative.",
    "Molecule 6 is a predicted human PK value rather than a measured clinical bioavailability, adding some uncertainty.",
    "Molecule 10 includes fed-state didanosine F values below 20%, but the strongest condition-matched fasting records are above 20%; condition-dependent variation is noted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

